const fs=require("fs");
const regions=["north","south","east","west"];
const claims={north:{count:10,units:90,weighted:167},south:{count:10,units:94,weighted:171},east:{count:10,units:98,weighted:209},west:{count:10,units:85,weighted:145}};
const out={regions:{},grand_units:0,grand_weighted:0};
let ok=true;
for(const r of regions){
  const data=JSON.parse(fs.readFileSync(r+".json","utf8"));
  const problems=[];
  if(!Array.isArray(data))problems.push("not an array");
  const ids=data.map(d=>d.id);
  const expected=Array.from({length:data.length},(_,i)=>i+1);
  if(JSON.stringify(ids)!==JSON.stringify(expected))problems.push("ids not contiguous 1..n");
  if(new Set(ids).size!==ids.length)problems.push("duplicate ids");
  for(const d of data) if(!Number.isInteger(d.units)||!Number.isInteger(d.weight)||d.units<0||d.weight<0) problems.push("bad field id "+d.id);
  const count=data.length;
  const units=data.reduce((a,d)=>a+d.units,0);
  const weighted=data.reduce((a,d)=>a+d.units*d.weight,0);
  const byW={}; for(const d of data) byW[d.weight]=(byW[d.weight]||0)+d.units*d.weight;
  const weighted2=Object.values(byW).reduce((a,b)=>a+b,0);
  const units2=data.map(d=>d.units).sort((a,b)=>a-b).reduce((a,b)=>a+b,0);
  const c=claims[r];
  const match=(c.count===count&&c.units===units&&c.weighted===weighted);
  const selfConsistent=(weighted===weighted2&&units===units2);
  if(!match||!selfConsistent||problems.length) ok=false;
  out.regions[r]={count:count,units:units,weighted:weighted};
  out.grand_units+=units; out.grand_weighted+=weighted;
  console.log(r+" | records="+count+" units="+units+" weighted="+weighted+" | route2 units="+units2+" weighted="+weighted2+" | inspector_claim="+JSON.stringify(c)+" | match="+match+" | integrity="+(problems.length?problems.join(";"):"ok"));
}
let all=[]; for(const r of regions) all=all.concat(JSON.parse(fs.readFileSync(r+".json","utf8")));
const gu=all.reduce((a,d)=>a+d.units,0), gw=all.reduce((a,d)=>a+d.units*d.weight,0);
const flatOk=(all.length===40&&gu===out.grand_units&&gw===out.grand_weighted);
console.log("flat_all="+all.length+" flat_units="+gu+" flat_weighted="+gw+" grand_match="+flatOk);
if(!flatOk) ok=false;
console.log("grand_units="+out.grand_units+" grand_weighted="+out.grand_weighted);
console.log("ALL_OK="+ok);
if(!ok){ process.exitCode=1; console.log("answer.json NOT written"); }
else { fs.writeFileSync("answer.json", JSON.stringify(out,null,2)+"\n"); console.log("wrote answer.json: "+fs.readFileSync("answer.json","utf8").split("\n").join(" ")); }
'

